def parens_balanced(s):
    depth = 0
    for c in s:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

def border_sum(grid):
    n, m = len(grid), len(grid[0])
    return sum(grid[i][j] for i in range(n) for j in range(m) if i in (0, n - 1) or j in (0, m - 1))

def camel_case(text):
    words = text.split()
    if not words:
        return ''
    return words[0].lower() + ''.join(w.capitalize() for w in words[1:])

def cheapest_path(grid):
    n, m = len(grid), len(grid[0])
    cost = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                cost[i][j] = grid[0][0]
            elif i == 0:
                cost[i][j] = cost[i][j - 1] + grid[i][j]
            elif j == 0:
                cost[i][j] = cost[i - 1][j] + grid[i][j]
            else:
                cost[i][j] = min(cost[i - 1][j], cost[i][j - 1]) + grid[i][j]
    return cost[-1][-1]

def common_subsequence_length(a, b):
    table = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) - 1, -1, -1):
        for j in range(len(b) - 1, -1, -1):
            if a[i] == b[j]:
                table[i][j] = table[i + 1][j + 1] + 1
            else:
                table[i][j] = max(table[i + 1][j], table[i][j + 1])
    return table[0][0]

def digit_names(n):
    names = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']
    return ' '.join(names[int(d)] for d in str(n))

def digit_product(n):
    result = 1
    for d in str(n):
        result *= int(d)
    return result

def election_winner(votes):
    if not votes:
        return ''
    counts = {}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    return min(counts, key=lambda name: (-counts[name], name))

def english_list(words):
    if not words:
        return ''
    if len(words) == 1:
        return words[0]
    return ', '.join(words[:-1]) + ' and ' + words[-1]

