def fewest_steps(grid):
    from collections import deque
    n, m = len(grid), len(grid[0])
    if grid[0][0] < 0 or grid[n - 1][m - 1] < 0:
        return -1
    dist = {(0, 0): 0}
    queue = deque([(0, 0)])
    while queue:
        i, j = queue.popleft()
        if (i, j) == (n - 1, m - 1):
            return dist[(i, j)]
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < n and 0 <= b < m and grid[a][b] >= 0 and (a, b) not in dist:
                dist[(a, b)] = dist[(i, j)] + 1
                queue.append((a, b))
    return -1

def luhn_check_digit(n):
    total = 0
    for i, c in enumerate(reversed(str(n))):
        d = int(c)
        if i % 2 == 0:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return (10 - total % 10) % 10

def missing_between(numbers):
