    result = []
    for i, x in enumerate(numbers):
        j = i
        while j > 0 and numbers[j - 1] <= x:
            j -= 1
        result.append(i - j + 1)
    return result

def run_stack(numbers):
    stack = []
    for x in numbers:
        if x > 0:
            stack.append(x)
        elif x < 0 and stack:
            stack.pop()
    return stack

def subset_adds_to(numbers, target):
    sums = {0}
    for x in numbers:
        sums |= {s + x for s in sums}
    return target in sums

def summarize_ranges(numbers):
    parts = []
    i = 0
    while i < len(numbers):
        j = i
        while j + 1 < len(numbers) and numbers[j + 1] == numbers[j] + 1:
            j += 1
        parts.append(str(numbers[i]) if i == j else f'{numbers[i]}..{numbers[j]}')
        i = j + 1
    return ', '.join(parts)

def three_add_up_to(numbers, target):
    import itertools
    return any(a + b + c == target for a, b, c in itertools.combinations(numbers, 3))

